/* =========================================================
   MGODWILL+ BOOKS  (books.js)
   Version 1.0

   Books that can be read online. It never touches catalogue.js.
   Fields: id, title, subtitle, author, description, cover, pdf,
   chapters. Chapter blocks: p = paragraph, v = stanza (list of
   lines), h = small heading, s = sign-off line.
   ========================================================= */

const MGODWILL_BOOKS = [
{
  id: "silly-testament",
  title: "The Silly Testament",
  subtitle: "A Scholar’s Guide to Absolute Nonsense",
  author: "Prof. Gigglesworth von Buffoonery, PhD (in Preposterous Studies)",
  description: "A poetic master class in satire and absurdity, mocking everything from business to philosophy with irony, sarcasm and wisdom that makes no sense, yet somehow does. If logic is your thing, prepare to be disappointed!",
  cover: "silly-testament-cover.jpg",
  pdf: "The_Silly_Testament.pdf",
  chapters: [
    {"t": "Author’s Note", "p": "Front matter", "b": [["s", "Dear Scholars of Supreme Silliness,"], ["p", "Welcome to The Silly Testament: A Scholar’s Guide to Absolute Nonsense—a groundbreaking, earth-shattering, mind-expanding literary achievement (at least according to the one person who wrote it—me). This book is not sponsored by any company, government, secret society, or billionaire who faked his own death. No politicians, businessmen, preachers, philosophers, or local herdsmen were harmed in the making of this masterpiece—though some of their logic may not survive intact."], ["p", "Let it be known: no offense is intended, no lawsuits are welcome, and no goats were consulted during the writing of this book. If you laugh, excellent. If you question everything you once believed, even better. If you find yourself deeply confused… perfect."], ["p", "This is not just a book—it’s a scholarly nonsense manifesto, a humorous critique of the unquestioned, and a celebration of the fine art of not taking life too seriously. Read, reflect, and most importantly, embrace the delightful absurdity of it all."], ["s", "Yours in eternal mischief,"], ["s", "Professor Gigglesworth von Buffoonery, PhD"], ["s", "(in Preposterous Studies)"], ["s", "Supreme Chancellor of Absurd Affairs"]]},
    {"t": "Review by Professor Ludmilla P. Noodledoodle, Chancellor of the Institute of Unnecessary Brilliance, Luxembourg", "p": "Front matter", "b": [["p", "Ah, The Silly Testament: A Scholar’s Guide to Absolute Nonsense! A book so ludicrously profound, so absurdly enlightening, that it makes one question not just life, but the very act of reading itself. I must say, few works have dared to walk the razor-thin line between genius and absolute buffoonery quite like this one. And if anyone could achieve such an impossible feat, it is none other than my dear colleague, the indomitable Professor Gigglesworth von Buffoonery, PhD (in Preposterous Studies)."], ["p", "I first met the good professor at the International Symposium of Dubious Knowledge, where he delivered a keynote speech titled \"The Art of Saying Something While Saying Nothing at All.\" It was a masterpiece of intellectual acrobatics, and since that day, I have followed his career with great admiration (and occasional bewilderment). His past achievements include disproving the existence of common sense, legally declaring himself “Too Silly to Sue,” and winning an award for Most Unnecessarily Complicated Explanation of a Simple Concept. Truly, his credentials speak for themselves (mostly in tongues no one understands)."], ["p", "This book, much like the man himself, is a paradox wrapped in satire, sprinkled with absurdity, and marinated in sheer brilliance. It asks the questions no one dares to ask, mocks what was once considered unmockable, and somehow turns nonsense into wisdom. A must-read for anyone who has ever looked at the world and thought, Surely, this can’t be serious?"], ["p", "Five out of five imaginary stars."], ["s", "Professor Ludmilla P. Noodledoodle"], ["s", "Chancellor, Institute of Unnecessary Brilliance, Luxembourg"], ["s", "Winner of the 2023 Award for Most Thought-Provoking Yet Completely Useless Research"]], "short": "Review by Professor Ludmilla P. Noodledoodle"},
    {"t": "Preface", "p": "Front matter", "b": [["p", "Ladies, gentlemen, and undecided thinkers,"], ["p", "Welcome to The Silly Testament: A Scholar’s Guide to Absolute Nonsense—a book so profoundly unnecessary yet undeniably essential that it may cause intellectual whiplash."], ["p", "This is not your average philosophical work. It is not a self-help book (unless you need help embracing absurdity), nor is it a revolutionary manifesto (unless the revolution is against seriousness itself). It is, however, a deeply academic, highly sophisticated, and utterly ridiculous exploration of life’s grandest contradictions."], ["p", "Here, we mock what was once thought unmockable. We analyze the things society refuses to question. We poke holes in logic so large you could fit an entire government budget inside. If you have ever wondered why the world insists on taking itself so seriously while constantly proving it shouldn’t be, this book is for you."], ["p", "Now, a warning: No sacred cows were spared, but no offense was intended. If you find yourself laughing, congratulations—you are officially a scholar of silliness. If you feel slightly attacked, consider that maybe—just maybe—this book is exactly what you need."], ["p", "Prepare yourself for a journey of wisdom, nonsense, and inconvenient truths, all wrapped in the most ridiculous package possible. Read, question, and above all… stay silly."], ["s", "Yours in unnecessary academia,"], ["s", "Professor Gigglesworth von Buffoonery, PhD (in Preposterous Studies)"], ["s", "Supreme Chancellor of Absurd Affairs"]]},
    {"t": "Introduction", "p": "Front matter", "b": [["p", "Ladies, gentlemen, and legally undefined entities, welcome to The Silly Testament—a scholarly guide to absolute nonsense, a philosophical misadventure, and perhaps the most important book you’ll read today (unless you also have a cereal box nearby)."], ["p", "Before you proceed, let me be clear: this book is not here to educate you, enlighten you, or lead you to financial freedom in just three easy steps. It is here to challenge everything you think you know using the ancient and noble art of Sillysism—a discipline so rigorous that it requires neither proof nor logic, just a willingness to embrace the absurd."], ["p", "Throughout history, humans have prided themselves on their intelligence, their systems of law, governance, business, fashion, and—most hilariously—their sense of self-importance. But what if all of it, from the stock market to marriage vows, from democracy to sobriety, is just an elaborate prank played on us by the universe? What if, in the grand hierarchy of wisdom, the fools have always been the real geniuses?"], ["p", "This book seeks to examine (or mock, depending on how serious you are) everything from pointless advertising to the baffling rituals of modern life. With each poem, we will question the unquestionable, satirize the untouchable, and laugh at the respectable—all in the most professorially silly manner possible."], ["p", "I, Professor Gigglesworth von Buffoonery, PhD (in Preposterous Studies), have spent an illustrious career dedicated to the pursuit of nonsense. My research into the loopholes of society, the contradictions of human behavior, and the comical failure of so-called “logic” has led me to a singular conclusion: nothing makes sense, and that’s exactly why we should laugh at it."], ["p", "So, dear reader, loosen your tie, set your critical thinking skills to \"mildly skeptical,\" and prepare to embark on a journey through the absurd. May you emerge either profoundly enlightened or at least mildly entertained."], ["p", "Now, let the Sillysism begin."]]},
    {"t": "The Sensible Stupidity", "p": "The Starting", "b": [["v", ["Ladies and gentlemen, sit tight, be flexible,", "Today, I shall prove the truth’s quite perplexible.", "The sensible folk, so proud and reliable,", "Are, in fact, rather dumb—quite undeniable."]], ["v", ["Observe the scholar, so wise, so methodical,", "Yet lost in a room that is wholly symmetrical.", "His glasses sit perched, he speaks mathematical,", "Yet pays for advice from a man who’s fanatical."]], ["v", ["The businessman, sharp, precise, oh so tactical,", "Yet buys a new watch—now time is more practical!", "He saves every shilling, invests in the stock,", "Then spends it all later on rocks for his walk."]], ["v", ["Ah, politicians, those minds so incredible,", "Their speeches so vague, yet somehow commendable.", "They promise the moon, the stars, the whole sky,", "Yet tax you for air—oh, what a guy!"]], ["v", ["The scientist claims his method’s infallible,", "Yet changes his theory when grants are more valuable.", "He told us that fats were the devil’s own fuel,", "Now butter’s a hero—was I just a fool?"]], ["v", ["Let’s not forget the finance professional,", "Calculating numbers, so cold, so exceptional.", "Yet his own wallet is thinner than mist,", "Perhaps he misplaced his financial list?"]], ["v", ["The serious ones scoff at all things impractical,", "Yet drive to the gym—why not walk? It’s more tactical!", "They buy bottled water—how very respectable,", "Yet cry when they check that it’s wholly collectible."]], ["v", ["The legal expert, all noble and factual,", "Yet laws seem to change when the client is capital.", "Steal one shilling, you’ll rot in the pen,", "Steal a whole nation? You’ll rule once again!"]], ["v", ["Ladies and gents, this brings me to Sillysism,", "A doctrine immune to the sensible’s schism.", "Behold the great truth—life’s purely satirical,", "To take it too serious is frankly hysterical."]], ["v", ["So loosen your ties, embrace the irrational,", "The world’s but a joke—so why be so national?", "The wise are the fools, the fools are the free,", "Now who, dear audience, would you rather be?"]]]},
    {"t": "The Doctrine of Dumbness", "p": "The Starting", "b": [["v", ["Ah, welcome, my pupils, to today’s intellectual,", "Where logic is rigid, yet quite ineffectual.", "I present to you now a case most regrettable,", "How wisdom itself can be wholly forgettable."]], ["v", ["Observe the economist, noble, statistical,", "Charts and projections—oh, so analytical.", "Yet ask him to budget his salary right,", "He’ll be in overdraft by tomorrow night."]], ["v", ["The fitness guru, so shredded, unshakable,", "Yet sneaks in a burger—how very relatable!", "He preaches of macros, of fasting, of gains,", "Yet struggles to jog when it slightly rains."]], ["v", ["The digital moguls, all techy and virtual,", "Sell data as if it's a practice quite neutral.", "They whisper of freedom, encryption, and trust,", "Yet track every move—how utterly just!"]], ["v", ["Historians write of the past most dramatical,", "Yet half of their sources are wholly fanatical.", "They claim that their books are accurate, clinical,", "Yet every edition rewrites the original."]], ["v", ["The banker insists that cash is disposable,", "Yet somehow his bonus is never negotiable.", "He tells you to save, to think long and wise,", "While gambling your funds in a system of lies."]], ["v", ["Academics discuss all things hypothetical,", "Dissertations on topics that feel alphabetical.", "They argue for years on a subject so minuscule,", "Yet none of their work is remotely producible."]], ["v", ["Lawmakers draft up the rules of the nation,", "Then break them themselves—ah, what dedication!", "Justice, they say, is blind and fair,", "Yet if you have money, it suddenly cares."]], ["v", ["Oh, dear students, the truth is quite laughable,", "The sensible ones are indeed most gullible.", "For those who embrace the ways of the silly,", "Shall dance through life all light and frilly."]], ["v", ["So cast off the chains of serious demeanor,", "And see the world as its true silly theater.", "For reason itself is a joke most reliable,", "And wisdom, my friends, is wholly deniable!"]]]},
    {"t": "The Scholarly Scam", "p": "The Starting", "b": [["v", ["Ah, welcome, my students, please open your manual,", "Today we discuss why school is a scandal.", "They call it essential, the path to success,", "Yet most of the rich ones just skipped all the tests!"]], ["v", ["They teach you equations, all square and symmetrical,", "Yet none of them help when your bills get identical.", "They force you to memorize kings from the past,", "But not how to budget—oh, what a farce!"]], ["v", ["They give you a grade and claim it’s reliable,", "Yet genius itself is barely gradable.", "They say, “Stay in class, don’t waste your potential,”", "Then hand you a debt that’s wholly unpayable."]], ["v", ["You study for years, you sweat, you revise,", "Yet land in a job that pays you in sighs.", "The teacher, so strict, so wise and formidable,", "Yet somehow his salary’s barely livable."]], ["v", ["They preach of success through reading and grammar,", "Yet billionaires dropped out—now ain't that a hammer?", "They say, “Raise your hand, don’t speak out of turn,”", "Yet in boardrooms, it’s chaos where paychecks are earned."]], ["v", ["The history books? Oh, they’re quite theoretical,", "For half of the facts are barely historical.", "They teach you of wars, of empires so grand,", "Yet never explain who really had planned."]], ["v", ["They say education expands your whole mind,", "Yet punish the kid who dares to ask, “Why?”", "They grade your ability to follow instructions,", "Yet tell you that thinking’s the key to production."]], ["v", ["They tell you, “Sit still, be calm, stay in line,”", "Yet in the real world, it’s hustle or die.", "They teach you to fear the almighty red pen,", "Yet CEOs scribble like five-year-old men!"]], ["v", ["So tell me, dear students, if school is so great,", "Why do its lessons expire with fate?", "For wisdom’s not found in a room with a bell,", "But out in the world, where the idiots sell!"]], ["v", ["So throw out your homework, embrace Sillysism,", "For school is just rules inside a big prison.", "Go out, ask questions, be foolish, be free,", "And learn from the world—not just a degree!"]]]},
    {"t": "The Infallible Fallible", "p": "The Starting", "b": [["v", ["They said the system’s logical, methodical, radical,", "But why’s it so tragical, magical, theatrical?", "If truth is adaptable, stretchable, flexible,", "Then how’s it still credible, stable, infallible?"]], ["v", ["They call it empirical, mystical, clinical,", "Yet somehow political, mythical, cynical.", "They say it's unbreakable, solid, dependable,", "But who's out here making it so expendable?"]], ["v", ["Is knowledge quantifiable, stackable, grabbable?", "Or just some illusion that's barely relatable?", "They say that the experts are truly impeccable,", "But ain't half their theories just quite forgettable?"]], ["v", ["If gravity’s pulling, then why ain't we falling?", "And if time is moving, then why ain't we stalling?", "They claim that the past is all factual, actual,", "But ain't history written by men who are tactical?"]], ["v", ["They say the intangible’s fake and ignorable,", "Yet money’s just numbers, so how’s it adorable?", "The laws are immutable, strict and reliable,", "Yet somehow for some, they be oddly pliable."]], ["v", ["If life is statistical, wholly predictable,", "Then why’s it so baffling, deeply despicable?", "If wisdom is noble, so rich and digestible,", "Then why’s it ignored till it’s unpreventable?"]], ["v", ["They speak philosophical, lofty, poetical,", "Yet most of their logic is borderline comical.", "If silence is golden and words are destructible,", "Then why do they talk till it’s just indigestible?"]], ["v", ["They say that the science is cold and mechanical,", "Yet somehow it shifts when the sponsors are radical.", "They claim that their models are truly impeccable,", "But ain't they just tweaking them till they're acceptable?"]], ["v", ["If numbers don’t lie, then why they so fickle?", "Inflation’s still rising, but money’s a trickle.", "They say that the world is all fair and equitable,", "But ain't it just rigged to be quite unlivable?"]], ["v", ["If laws are impartial, just, and identical,", "Then why do some break 'em yet seem untouchable?", "They claim that the wealth gap is barely discernible,", "But check where they live—it’s quite observable."]], ["v", ["They call it democracy, fair and relatable,", "But ain't it just theater that’s purely debatable?", "They say we got freedom, unlimited, infinite,", "Yet somehow our choices are barely legitimate."]], ["v", ["They preach all their isms—capital, liberal,", "But ain't they just methods to keep us all minimal?", "If all of this logic is solid and factual,", "Then why does it feel so deeply theatrical?"]], ["v", ["Now answer me this, if you truly are able:", "Is knowledge itself just a mythical fable?"]]]},
    {"t": "The Grand Illusion of Laws and Democracy", "p": "The Starting", "b": [["v", ["Ah, students, today we discuss something remarkable,", "A system so perfect, yet wholly laughable.", "They call it democracy—wise and impeccable,", "Yet somehow the fools remain most electable!"]], ["v", ["Laws, they claim, are firm and reliable,", "Yet bend for the rich—how very pliable!", "They say, “Justice is blind,” so noble, so factual,", "Yet somehow it peeks when the bribe is substantial."]], ["v", ["They say, “Vote wisely, your voice is essential,”", "Yet all the candidates are wholly identical!", "One steals with pens, the other with speeches,", "Yet both take your money and call them their riches."]], ["v", ["The constitution—oh, how very historical,", "A document sacred yet wholly rhetorical.", "They amend it, rewrite it, twist it, abuse it,", "Yet punish the fool who dares to confuse it!"]], ["v", ["“Obey the law,” they say with a frown,", "Yet half of the lawmakers should be locked down.", "They write up new rules—so legal, so grand,", "Yet loopholes appear when money’s in hand."]], ["v", ["“Elections are fair,” they boldly declare,", "Yet ballots seem counted before they get there!", "They rally, they chant, they promise, they scream,", "Yet somehow your taxes still fund their regime."]], ["v", ["They fine you for speeding—a terrible sin,", "Yet those in convoys? Oh, let them begin!", "They make rules for you, for order and peace,", "Yet laws, it appears, are mere guidelines for elites."]], ["v", ["Parliament debates—oh, what a sight!", "They argue for hours, yet solve not a mite.", "They ban what they hate, they tax what they can,", "Then vanish abroad for “official” plans."]], ["v", ["They tell you to trust, to believe, to obey,", "Yet whistleblowers seem to just fade away.", "They say the system is fair, oh how delightful,", "Yet corruption itself is wholly insightful."]], ["v", ["So, my dear students, be wise, be aware,", "For laws are illusions, just vapor in air.", "Democracy’s grand, but if you look near,", "It’s just a circus, so grab some beer!"]]]},
    {"t": "The Mediocre Media", "p": "The Starting", "b": [["v", ["Ah, students, today’s class is exceptional,", "We’ll discuss the media—so wise, so professional.", "A beacon of truth, so grand, so reliable,", "Yet somehow their facts are wholly pliable."]], ["v", ["They report with vigor, with passion unshakable,", "Yet their sources are vague, their claims undebatable.", "A scandal, a crisis, a world-ending riot,", "Yet once ratings drop, all goes quiet."]], ["v", ["They scream “BREAKING!”—oh, what a thrill,", "Yet yesterday’s news lies unpaid on the sill.", "They spin every tale, they shape every view,", "And if facts don’t align, they just make up a few."]], ["v", ["The journalist stands with posture so noble,", "Yet bends like a twig when the paycheck is global.", "Truth is their mission, they claim with pride,", "Yet truth takes a nap when sponsors decide."]], ["v", ["They love a good panic—oh, what a trick!", "Today it’s disease, tomorrow’s a conflict.", "They’ll warn you of chaos, of terror, of pain,", "Then break for commercials—oh, buy this new chain!"]], ["v", ["The anchors, so sharp, so neat, so composed,", "Yet somehow their thoughts are producer-imposed.", "They nod, they react, they furrow their brows,", "Yet whisper the script that’s fed through their earpiece now."]], ["v", ["They interview leaders, so bold, so demanding,", "Yet all the real questions remain notwithstanding.", "They grill the weak, they corner the small,", "Yet bow to the rich like servants in halls."]], ["v", ["And let’s not forget the headlines—subliminal!", "\"Experts Predict!\"—yet facts are minimal.", "\"A Shocking Report!\"—so vague, yet dramatic,", "\"Will You Survive?\"—oh, how cinematic!"]], ["v", ["The news cycle spins, never-ending, eternal,", "Yet truth disappears like smoke from a journal.", "For facts are too dull, too slow, too plain,", "So spice them with fear and repeat them again!"]], ["v", ["So, students, beware when media speaks,", "For truth in their hands is a circus of tricks.", "If reality’s dull, they’ll craft a good story,", "For panic and clicks mean profit and glory!"]]]},
    {"t": "The Legal Labyrinth: A Guide to Lawful Lawlessness", "p": "The Starting", "b": [["v", ["Ah, students, today’s lesson is critical,", "We dissect the law—so firm, yet mystical.", "They say it's fair, just, and applicable,", "Yet somehow, it's also adjustable."]], ["v", ["“Justice is blind,” they chant so lyrical,", "Yet money restores its full vision—miracle!", "They tell you, “The law is equal for all,”", "Yet bail is a ladder, and the poor always fall."]], ["v", ["They fine you for theft—so noble, so great,", "Yet corruption’s a crime that just gets a debate.", "A hungry man steals? Oh, lock him inside!", "A banker embezzles? Just resign and hide."]], ["v", ["You cannot bribe, it’s illegal, they say,", "Yet call it a “gift,” and it’s perfectly okay!", "A handshake, a favor, a trip overseas,", "Congratulations, my friend, you’re now legal with ease."]], ["v", ["Speeding is wrong, they fine you with passion,", "Yet escorts fly past—ah, that’s just fashion!", "You must obey traffic and follow the law,", "Unless you have sirens, then break them all!"]], ["v", ["They jail the addict, so hopeless, so weak,", "Yet praise the dealer in a suit when he speaks.", "A gram in your pocket? Oh, that's a crime,", "But smuggle a ton, and you’ll be just fine."]], ["v", ["“Elections are fair,” they claim with a grin,", "Yet somehow the winner was chosen last spring.", "Votes are collected, ballots are tossed,", "Yet only the rich can afford to have lost."]], ["v", ["They say, “Speak freely, the law’s on your side,”", "Yet one wrong opinion, and lawsuits arrive.", "Critique the elite? Oh, now you’re in danger!", "Call it defamation, and hire a stranger."]], ["v", ["Contracts are binding—oh, such a treasure!", "Unless you're too rich, then break them at pleasure.", "A small man defaults? He’s sued till he’s sore,", "A billionaire fails? He’s restructured once more."]], ["v", ["Ah, dear students, the law is exquisite,", "A tool for the powerful, a cage for the timid.", "For justice is not about right or wrong,", "It’s about who can pay to move it along."]], ["v", ["So study your rights, be clever, be wise,", "And when laws seem solid, just look with new eyes.", "For loopholes exist, like doors left ajar,", "And the law’s just a maze—if you know where you are."]]]},
    {"t": "The Business of Loopholes", "p": "The Starting", "b": [["v", ["Ah, students, today’s class is invaluable,", "We’ll learn how business stays untouchable.", "They teach you that markets are free and fair,", "Yet somehow the billionaires own all the air!"]], ["v", ["Taxes, they say, are duties most noble,", "Yet somehow the rich make theirs invisible.", "They hide their gold in lands offshore,", "While you pay the fee at the grocery store."]], ["v", ["Laws are clear, oh yes, so readable,", "Yet full of clauses—so breakable, bendable.", "A worker complains? Oh, give him a fine,", "A CEO robs? “It’s a strategy—divine!”"]], ["v", ["Monopolies? No, that’s illegal, you see,", "Yet somehow one company owns all the tea.", "Mergers, acquisitions, a boardroom handshake,", "Now every competitor just vanished—how great!"]], ["v", ["They fine a big bank for laundering crime,", "Yet somehow no banker does even one time.", "A million-dollar fraud? A mere slap on the wrist,", "Yet shoplift a soda, and prison insists."]], ["v", ["They say, “Pay your workers, be honest, be fair,”", "Yet bonuses triple while wages despair.", "You clock in, you grind, you bleed, you persist,", "Yet somehow, your paycheck just doesn’t exist."]], ["v", ["Bankruptcy—oh, what a delightful escape,", "For billionaires, it’s a plan well-shaped.", "They “lose” all their money, they vanish, they hide,", "Yet months later, they're somehow revived."]], ["v", ["Laws against fraud? Oh, they exist!", "Yet loopholes turn them into a mist.", "It’s not “lying,” it’s “marketing flair,”", "It’s not a scam, it’s “customer care.”"]], ["v", ["They say the market is driven by choice,", "Yet ads hypnotize, so you lose your own voice.", "The contract’s unfair? Oh, that’s a shame,", "But sign on the line—you agreed to the game!"]], ["v", ["So, dear students, if wealth is your goal,", "Forget hard work—just learn loophole control.", "The law is a maze, not built to be fair,", "It’s built for the clever—so rewrite it with flair!"]]]},
    {"t": "The Great War of General Bombington & Sir Bulletsworth", "p": "The Starting", "b": [["v", ["Ah, students, today’s case is historical,", "A tale of leaders—so brave, so tactical!", "General Bombington, so wise, so logical,", "And Sir Bulletsworth, his twin—so methodical!"]], ["v", ["They march with honor, their speeches divine,", "Yet somehow, the profits are never benign.", "They shout, “For freedom! For peace! For the land!”", "Yet weapons keep selling—supply meets demand."]], ["v", ["A crisis appears? Oh, what a delight!", "Sir Bulletsworth sharpens his missiles at night.", "Diplomacy? Talks? Oh, that’s too slow,", "Just bomb the village—progress must flow!"]], ["v", ["They cry, “We fight for justice, for law!”", "Yet steal all the oil—oh, what a flaw!", "They draft the poor, the young, the bold,", "Yet watch from afar as the battles unfold."]], ["v", ["A peace deal is signed—oh, history’s grace!", "Yet somehow, war stocks shoot up in place.", "General Bombington grins, “We have prevailed!”", "Yet factories run, more weapons unveiled."]], ["v", ["The enemy? Oh, they change every year,", "One day it’s rebels, the next it’s your peers.", "They sell the weapons to both of the sides,", "Then claim, “We’re neutral!” while grinning with pride."]], ["v", ["Refugees flee, the world’s in despair,", "Yet Bombington smirks—\"We just need more air!\"", "He orders more drones, more strikes, more fights,", "Yet sleeps like a baby on silk sheets at night."]], ["v", ["The cycle continues—oh, how delightful!", "A war here, a war there—so insightful!", "They start with explosions, then act so concerned,", "Yet somehow, their bank accounts double in turn."]], ["v", ["Ah, dear students, war’s quite the art,", "You paint it with slogans, then tear it apart.", "And those who protest? Oh, what a shame!", "Just label them traitors and end the game."]], ["v", ["So next time you hear of a war that is “just,”", "Look for the contracts, the deals, and the trust.", "For General Bombington and Sir Bulletsworth too,", "Are just selling destruction—straight to you."]]]},
    {"t": "The Holy Union of Mr. & Mrs. Regret", "p": "The Starting", "b": [["v", ["Ah, students, today’s lesson is marital,", "A bond so sacred—yet oddly satirical.", "They say love’s eternal, a magical trance,", "Yet half end up splitting the house and the plants."]], ["v", ["The wedding is grand, a national thrill,", "Yet after a month, they argue the bill.", "“For richer, for poorer!” they boldly declare,", "Yet fight when the paycheck just isn’t there."]], ["v", ["They post their vows, oh, love so divine!", "Yet swipe right on Tinder at the very same time.", "They promise forever, through thick and through thin,", "Yet plot their escape the moment they’re in."]], ["v", ["Ah, the honeymoon—what a beautiful trick!", "A trip to the islands, romantic and slick.", "Yet back in the house, with no place to hide,", "They learn that love has a snoring side."]], ["v", ["The wife wants gifts, she measures romance,", "The husband’s confused—\"Isn’t rent in advance?\"", "She wants affection, he wants some peace,", "Yet somehow their love contract missed these fine fees."]], ["v", ["“In-laws are family, they’re part of the deal!”", "Yet soon they invade like armies with steel.", "She hates his mother, he hates her dad,", "Yet both still pretend that it isn’t that bad."]], ["v", ["Ah, and the kids—what a joyful surprise!", "Until they arrive with their infinite cries.", "Sleep disappears, peace is a dream,", "Yet they nod and they smile—“Oh, what a team!”"]], ["v", ["Soon, there’s counseling—“Let’s fix what is broke!”", "Yet both have been texting their high school bloke.", "Divorce is discussed, but wait—there’s the cost,", "So now they’re just roommates, emotionally lost."]], ["v", ["Yet weddings continue, with flowers and songs,", "A cycle repeating, ignoring the wrongs.", "For love is a story, a film, a parade,", "And logic? Oh please—that’s just getting in the way!"]], ["v", ["So students, beware, take marriage with care,", "Or join Mr. Regret in his thousand-yard stare.", "For weddings are lovely, but contracts deceive,", "And true love, dear scholars, is hard to achieve!"]]]},
    {"t": "The Tragic Tale of Mr. Sober & His Boring Life", "p": "The Starting", "b": [["v", ["Ah, students, today’s case is clinical,", "A life so dull, so painfully typical.", "Meet Mr. Sober—so wise, so sensible,", "Yet somehow his joy is barely detectable."]], ["v", ["He wakes up at six—oh, what a delight!", "Drinks warm lemon water, oh what a sight!", "“No caffeine, no sugar, no alcohol too,”", "Yet somehow, his face looks ready to sue."]], ["v", ["He jogs every morning—“Health is the key!”", "Yet frowns at the kids just climbing a tree.", "He eats only greens, avoids all the fries,", "Yet somehow, his soul is the one that just dies."]], ["v", ["No parties, no drinks, no music too loud,", "Yet wonders why life feels stuck in a cloud.", "“No dancing, no jokes, let’s all be mature,”", "Yet somehow, his friendships feel deeply unsure."]], ["v", ["He preaches of discipline, lectures on time,", "Yet somehow his fun is considered a crime.", "“No nonsense, no laughter, no reckless delight,”", "Yet every night, he just stares at the light."]], ["v", ["“No smoking, no gambling, no breaking the law,”", "Yet somehow, he’s jealous of those with a flaw.", "For rebels are laughing, the wild ones are free,", "While he just sits, sipping his herbal tea."]], ["v", ["Ah, but students, the best part is near,", "Mr. Sober has aged, oh, look at his fear!", "He saved all his money, worked all his life,", "Yet now he just stares—alone, no wife."]], ["v", ["He sees Mr. Tipsy, so broke yet so glad,", "Laughing at memories that Sober never had.", "And as he sighs, with his final regret,", "He whispers, “I should’ve just placed that one bet.”"]], ["v", ["So remember, dear students, life is absurd,", "Too much control and it all feels unheard.", "So raise a toast—to balance, to fun,", "And may your youth not be completely undone!"]]]},
    {"t": "The Righteous Reverend Saint Law-Abider", "p": "The Starting", "b": [["v", ["Ah, students, today’s case is biblical,", "A man so holy—yet strangely hypocritical.", "Meet Reverend Law-Abider, so pure, so clean,", "Yet somehow, his past is nowhere to be seen."]], ["v", ["He prays every morning, he fasts till he’s thin,", "Yet frowns at the poor like poverty’s a sin.", "He preaches of mercy, of kindness, of grace,", "Yet cuts in the queue with a smug little face."]], ["v", ["“No stealing, no cheating, no lies in my life!”", "Yet somehow, his pockets stay strangely ripe.", "“No sin shall I touch, I’m righteous and true,”", "Yet flirts with the choir girl right in the pew."]], ["v", ["He shouts, “No tattoos! No drinking! No weed!”", "Yet bribes the police when caught overspeed.", "He tithes with pride, his donation is grand,", "Yet somehow, his mansion just tripled in land."]], ["v", ["He calls for justice, for truth, for reform,", "Yet laws against church scams? “Oh, that’s not the norm.”", "He frowns at the youth in parties and clubs,", "Yet meets secret “guests” in expensive hubs."]], ["v", ["He preaches of patience, of peace, of the Lord,", "Yet fights for a title—\"Call me My Lord!\"", "He warns of damnation, of judgment, of sin,", "Yet somehow, his anger is holy within."]], ["v", ["A man is arrested, “He must pay the cost!”", "Yet Reverend Law-Abider? “Oh, he’s just lost.”", "His crime was a mistake, his faults washed away,", "Yet the thief on the street? “Oh, let him decay.”"]], ["v", ["He judges, he points, he boasts, he brags,", "Yet his own closet is packed full of flags.", "Flags of corruption, of scandal, of schemes,", "Yet still, he walks with the holiest gleam."]], ["v", ["Ah, dear students, beware the clean slate,", "For some use the law to cover their fate.", "And when you hear words so righteous, so grand,", "Just check if their pockets match what they demand."]]]},
    {"t": "The Great Romance of Sir Lovington the Desperate", "p": "The Starting", "b": [["v", ["Ah, students, today’s case is lyrical,", "A tale of love—so tragic, so comical.", "Meet Sir Lovington, a man so romantic,", "Yet somehow, his methods are deeply pedantic."]], ["v", ["He writes long poems, so sweet, so divine,", "Yet somehow, no woman responds to a line.", "He kneels in the rain, he cries in the park,", "Yet wonders why love won’t just leave him a mark."]], ["v", ["“Please love me, my darling, I’ll give you the moon!”", "Yet she just replies, “Sir, it’s barely past noon.”", "He showers her inbox with texts full of pain,", "Yet wonders why she blocked him again."]], ["v", ["He buys her flowers, perfumes, and rings,", "Yet somehow, her love is missing these things.", "He follows her posts, he likes every tweet,", "Yet somehow, she dates a man from the street."]], ["v", ["He calls her “My Queen,” “My Angel,” “My Sun,”", "Yet she prefers “Yo, babe, what’s up? You the one.”", "He reads her Shakespeare, he sings her a ballad,", "Yet she just replies, “That guy got a salad?”"]], ["v", ["Ah, but Sir Lovington just cannot see,", "That love is no puzzle, no desperate plea.", "For those who chase, who beg, who obsess,", "Are loved the least, they impress even less."]], ["v", ["And so he waits, his heart full of sorrow,", "Yet somehow, she marries a guy by tomorrow.", "A guy who just laughed, who made her feel free,", "While Sir Lovington planned a grand symphony."]], ["v", ["So students, beware, don’t beg, don’t plead,", "For love is a game where thirst doesn’t lead.", "Be silly, be careless, be fun, be unbothered,", "And watch as they chase you—completely unbothered."]]]},
    {"t": "The Cautious Chronicles of Sir Sensible the Boring", "p": "The Starting", "b": [["v", ["Ah, students, today’s case is tragical,", "A man so wise, yet strangely illogical.", "Meet Sir Sensible—so safe, so pure,", "Yet somehow, his life's just a long, dull tour."]], ["v", ["He fears the absurd, the reckless, the wild,", "Yet wonders why life feels flavorless, mild.", "“No risks, no madness, I must play it smart!”", "Yet somehow, he’s jealous of fools from the start."]], ["v", ["“No quitting my job, that’s way too insane!”", "Yet complains that his boss is rotting his brain.", "“No chasing my dreams, that’s foolish, that’s dumb!”", "Yet sighs every night, feeling lifeless and numb."]], ["v", ["“No dancing in rain, I’ll catch a disease!”", "Yet those who do seem ten times at ease.", "“No silly ideas, no jokes, no extreme!”", "Yet somehow, his boredom is choking his dream."]], ["v", ["He fears the unknown, the strange, the bizarre,", "Yet somehow, his joy never travels too far.", "He mocks the rebels, the bold, the unwise,", "Yet secretly wishes he’d lived their surprise."]], ["v", ["He watches the fearless, the ones who just leap,", "Yet tells himself, “No, their minds are too weak.”", "For safety, for logic, for comfort, for sense,", "Yet still, he just stares at life through a fence."]], ["v", ["Ah, but students, let’s learn from his pain,", "A life without madness is truly in vain.", "For what is existence if not a bit wild?", "A circus, a play, where rules are defiled!"]], ["v", ["So fear not the absurd, the weird, the unknown,", "For that is where life has truly been shown.", "And when you grow old, with no thrill to recall,", "You’ll wish you had danced in the rain after all."]]]},
    {"t": "The Prestige of Being Completely Useless", "p": "The Starting", "b": [["v", ["Ah, students, today’s case is magical,", "A skill so rare, yet fully impractical.", "Meet Sir Worthington, a man of great fame,", "Yet somehow, his work has no actual aim."]], ["v", ["He owns a diploma in theoretical naps,", "A master's in balancing spoons on his laps.", "A PhD earned in watching paint dry,", "Yet wonders why companies don’t reply."]], ["v", ["He knows every flag, each capital too,", "Yet can’t find a job—oh, what shall he do?", "He solves Rubik’s cubes in less than a blink,", "Yet still can't afford a well-cooked drink."]], ["v", ["He memorized digits of pi past a hundred,", "Yet wonders why rent has tripled and thundered.", "He speaks Latin fluently—oh, what a feat!", "Yet somehow, that skill won’t pay for his meat."]], ["v", ["He studies the history of chairs through the ages,", "Yet cries when he sees his financial wages.", "He built a machine that claps by itself,", "Yet begs for a loan to afford his shelf."]], ["v", ["Ah, but students, here lies the twist,", "His uselessness somehow makes him exist.", "For in a world where all strive to be best,", "He stands undefeated—no skills to contest."]], ["v", ["For money is fleeting, power is vain,", "Yet being useless? That shall remain.", "So let’s toast to nonsense, to skills with no gain,", "For uselessness, dear students, is never in vain."]]]},
    {"t": "The Grand Art of Selling Nothing", "p": "The Starting", "b": [["v", ["Ah, students, today’s case is theatrical,", "A trick so cunning, yet wholly impractical.", "Meet Sir Advertisimo, a marketing sage,", "Who sells you a dream—but forgets the page."]], ["v", ["“Buy this shampoo! It strengthens the roots!”", "Yet somehow, he’s bald from scalp to boots.", "“This phone has AI! It thinks like a brain!”", "Yet can’t even spell a word without pain."]], ["v", ["“This watch is exclusive, elite, and supreme!”", "Yet it ticks just the same as the one from a stream.", "“Our shoes make you faster, more stylish, more tall!”", "Yet somehow, you still trip and fall."]], ["v", ["“This toothpaste will change your whole dental career!”", "Yet it’s just minty foam—it all disappears.", "“This pen writes smoother, so silky, so clean!”", "Yet somehow, the ink dries up in between."]], ["v", ["“Drink this new soda, it’s fresh and organic!”", "Yet somehow, the sugar is borderline panic.", "“This car is luxurious, it screams of pure class!”", "Yet breaks down at every speed bump you pass."]], ["v", ["Oh, but students, here lies the riddle,", "They sell you the sizzle, but never the griddle.", "For logic is weak, and nonsense is strong,", "And that’s why you sing their dumb ad like a song."]], ["v", ["So beware the jargon, the glitter, the gloss,", "For marketing wins—but you take the loss.", "And when you next hear, “This product’s divine!”", "Just check if it’s truly better than mine."]]]},
    {"t": "The Gospel of Gucci and the Prophecy of Prada", "p": "The Starting", "b": [["v", ["Ah, students, today’s case is tragical,", "A cult so deep, yet fully illogical.", "Meet Sir Dripington, the king of couture,", "Who spends on designer—but sleeps on the floor."]], ["v", ["“These jeans are distressed, they’re art, they’re divine!”", "Yet somehow, they cost more than land in the Rhine.", "“This shirt has no logo, that makes it elite!”", "Yet somehow, it’s thinner than paper—how neat."]], ["v", ["“These sneakers? Oh, they were handmade in Rome!”", "Yet they fall apart when he jogs back home.", "“This bag is exclusive, just look at the brand!”", "Yet somehow, it’s smaller than the size of his hand."]], ["v", ["“These glasses cost thousands, they’re stylish, they flex!”", "Yet he squints to read simple street signs and texts.", "“This belt is supreme, it makes me look tough!”", "Yet somehow, it’s just holding his pants up—enough."]], ["v", ["Ah, but students, here lies the joke,", "Fashion’s a tax for the rich and the broke.", "For style isn’t fabric, nor labels, nor trends,", "It’s simply the way that your confidence bends."]], ["v", ["So laugh at the fools who pay triple the price,", "For clothes they can’t wear more than once or twice.", "And next time they flex their “drip” with delight,", "Just ask, “Does it pay for your rent or your flight?”"]]]},
    {"t": "The Holy Gospel of Quick Cash & Miracles", "p": "The Starting", "b": [["v", ["Ah, students, today’s case is spiritual,", "A doctrine so deep, yet highly delusional.", "Meet Apostle Bankington, the prophet of gold,", "Who preaches that wealth is yours to behold."]], ["v", ["“God wants you rich! Just sow me a seed!”", "Yet somehow, he’s the only one freed.", "“Money will flow if your faith is aligned!”", "Yet his bank account’s the only one signed."]], ["v", ["“Give 10%, no—give even more!”", "Yet he drives a Benz while you clean the floor.", "“This anointing oil will triple your wage!”", "Yet somehow, your salary stays in a cage."]], ["v", ["“Repeat after me—‘I am rich! I am blessed!’”", "Yet your landlord still calls, distressed.", "“Stop working so hard, just name it, claim it!”", "Yet the only one cashing out is his favorite."]], ["v", ["“God hates the poor, He wants you to thrive!”", "Yet somehow, the pastor’s the only one alive.", "“The Lord told me—‘Someone must give!’”", "Yet it’s never him—it’s always you who must live."]], ["v", ["Ah, but students, here lies the twist,", "Their gospel’s a scam, yet people persist.", "For faith, when sold like stocks on a shelf,", "Only seems to work—for those preaching it themselves."]], ["v", ["So next time a prophet demands your last dime,", "Ask why God needs money—every single time.", "For if heaven is paved with pure golden delight,", "Why is the pastor still cashing in flights?"]]]},
    {"t": "The Gooners’ Gospel of Eternal Delusion", "p": "The Starting", "b": [["v", ["Ah, students, today’s case is comical,", "A faith so blind, yet strangely canonical.", "Meet Sir Arsenalus, a man full of pride,", "Who swears, “This year, we’ll turn the tide!”"]], ["v", ["“Trust the process! Just wait and believe!”", "Yet every season, they cry and they grieve.", "“We’re title contenders! Just watch, you’ll see!”", "Yet somehow, they finish in place number three."]], ["v", ["“We have the best squad! Our future is bright!”", "Yet their main striker can’t shoot left or right.", "“This manager’s genius, he’s building a team!”", "Yet every big match just shatters the dream."]], ["v", ["“This season is ours! We’re stronger than ever!”", "Yet February hits, and they’re choking the lever.", "“Our midfield’s elite! They control the game!”", "Yet one injury later, it’s never the same."]], ["v", ["“The referees hate us! It’s all just unfair!”", "Yet their defense disappears into thin air.", "“We’ll bounce back stronger, we’re built for success!”", "Yet every May ends in the usual mess."]], ["v", ["Ah, but students, here lies the pain,", "A cycle that loops again and again.", "For hope is a drug, and delusion is sweet,", "And that’s why Gooners stay glued to their seat."]], ["v", ["So let them keep chanting, let them believe,", "For football’s a play where dreams self-deceive.", "And when they say, “Next year, we rise!”", "Just smile, nod, and enjoy their demise."]]]},
    {"t": "The Grand Testament of Glorious Stupidity", "p": "The Starting", "b": [["v", ["Ah, students, today’s the grandest of days,", "A moment so ripe for ridiculous praise.", "For wisdom is dead, and nonsense is king,", "And logic’s been traded for marketing bling."]], ["v", ["We start with the rich men who preach about wealth,", "Yet somehow, their riches don’t share any stealth.", "“God wants you loaded! Just give me your stash!”", "Yet heaven takes prayers—while they take your cash."]], ["v", ["Then fashion arrives, draped in disgrace,", "Selling torn rags at a premium pace.", "“These jeans cost thousands, they’re stylish, they flex!”", "Yet they look like they lost a war with a T-Rex."]], ["v", ["Then step forth the Gooners, so loyal, so blind,", "Forever convinced that this is their time.", "“Trust the process! Our moment is near!”", "Yet every season just ends in a tear."]], ["v", ["Ah, but business! The realm of great schemes!", "Where laws have more loopholes than one ever dreams.", "The rich pay no taxes, yet fine you instead,", "For missing a deadline while earning your bread."]], ["v", ["And ads—oh, the prophets of magical things!", "Selling you nonsense with golden-winged strings.", "“This shampoo will bless your miserable hair!”", "Yet the seller is bald—does he simply not care?"]], ["v", ["Then democracy—oh, what a fine joke!", "The leaders all swear that they speak for the folk.", "Yet somehow, their speeches end in deceit,", "While they dine like kings and we beg for a seat."]], ["v", ["And then, my dear students, the sober elite,", "Who preach against drinks yet can’t stand on their feet.", "“Alcohol ruins! It rots you inside!”", "Yet somehow, their boredom kills more worldwide."]], ["v", ["And love! Oh, the fools who beg to be kissed,", "Who write silly poems just not to be missed.", "“Please don’t leave me! I’ll change, I’ll be new!”", "Yet love is no sale—there’s no discount for you."]], ["v", ["And fear—ah, the fear of the crazy, the mad!", "Yet those who seem normal are secretly bad.", "“Follow the rules! Behave and conform!”", "Yet the greatest of thinkers have laughed at the norm."]], ["v", ["So tell me, dear students, where does it end?", "Who truly profits, who truly pretends?", "Where do these laws get written and signed,", "And why do the loopholes leave justice behind?"]], ["v", ["Why do the holy not follow their book?", "Why does a prophet need wealth by the truck?", "Why do the rich claim struggle and strife,", "While sipping champagne on the edge of your life?"]], ["v", ["Why do the leaders all promise and lie?", "Why does a soldier agree just to die?", "Why do they teach us that school is the key,", "Yet the richest of all just dropped out—don’t you see?"]], ["v", ["Why is a car with a logo worth more?", "Why is a beggar ignored at the door?", "Why does a wedding cost all that you own,", "Yet half of those couples regret what they’ve sown?"]], ["v", ["Ah, but dear students, do not be afraid,", "For stupidity’s kingdom shall never degrade.", "It rises, it thrives, it swallows the wise,", "And sillysism—dear friends—shall open your eyes."]], ["v", ["So go forth in madness, in wisdom, in jest,", "For questioning everything makes you the best.", "And when they demand that you live by their rules,", "Just ask them one thing: Who profits from fools?"]]]},
    {"t": "The Testament of St. Maximilian Foshworthy", "p": "The Continuing", "b": [["v", ["Oh scholars, come closer, take out your pens,", "For nonsense and logic are barely just friends.", "A prophet, a jester, a lord of the daft,", "Maximilian Foshworthy, a scholar of craft."]], ["v", ["He dined with a fish—yes, in public, no shame,", "A meal so illegal, yet none knew his name.", "He strolled with a cow through streets all so fine,", "And broke ancient laws just to pass the time."]], ["v", ["His crime was grand, though silly at best,", "But what did he do? Ah, you must guess!", "A pardon he sought from a leader so bold,", "And lo! It was granted—his sins were untold."]], ["v", ["A billionaire’s heir, oh, such delight,", "His name in a will, his future so bright!", "But wealth is a phantom, a trick of the eye,", "For loopholes and lawbooks determine the lie."]], ["v", ["And then came his parents, oh, what a tale,", "He rewrote their love in a legal detail.", "A favorite declared by contract and seal,", "His sister dethroned—how splendid, how real!"]], ["v", ["Oh yes, the lawsuit! So petty, so grand,", "He took his own sibling straight to the stand.", "The charges? Absurd! The reasoning? Thin!", "Yet still, he declared, “I fight to win!”"]], ["v", ["He married a royal—oh, just for a day,", "A noble affair that faded away.", "The wedding was short, but the title stood tall,", "A prince in the morning, a fraud after all."]], ["v", ["And speaking of royals, let’s not forget,", "The Americans cheered—oh, how they were set!", "For Foshworthy was a prince (or so they all thought),", "A nobleman’s lie, so brilliantly wrought."]], ["v", ["His airline took flight—or well, not quite,", "A company’s name, but no planes in sight.", "A CEO’s throne, a boardroom so neat,", "Yet no one could fly, for there was no fleet!"]], ["v", ["A roundabout king, in traffic’s embrace,", "He owned a great circle—what a disgrace!", "A kingdom of tarmac, a throne in the street,", "A ruler of drivers with horns at his feet."]], ["v", ["Then came the millions—six minutes in gold,", "A fortune so grand, a story retold.", "Yet taxes arrived, and profits were slim,", "For money, dear scholars, is just a grand whim."]], ["v", ["He snuck into Congress, security tight,", "Yet there he was, in broad daylight!", "Delivering nonsense with confident grace,", "Yet none in the room could question his place."]], ["v", ["He welcomed the world to Luton one day,", "A sign of grand entry, or so he would say.", "The city stood puzzled, confused and bemused,", "For nonsense, dear friends, is best when infused."]], ["v", ["Then came the jobs, oh, what a spree!", "A CV on his car for the world to see.", "Yet somehow, it worked, his name was now known,", "A career built purely on wit over stone."]], ["v", ["He married for minutes, not even an hour,", "A contract of love that soon would go sour.", "Yet legally speaking, it still did count,", "For laws are just scribbles, with sums to amount."]], ["v", ["He adopted a grandpa—yes, he did that!", "A father by papers, a legal chit-chat.", "For love, dear students, is ink on a page,", "And families can form with laws as a gauge."]], ["v", ["Then fashion he mocked, the madness of style,", "How trends last seconds, then fade in a pile.", "A shoe with no laces, a coat with no sleeves,", "Yet somehow, they tell you, “It's what one believes.”"]], ["v", ["And marketing? Oh, the grandest of lies,", "A soap that brings wisdom, a cream for your eyes.", "A slogan so hollow, yet printed in gold,", "Convincing the masses to empty their hold."]], ["v", ["The get-rich sermons, oh, what a hoax!", "Preachers of wealth, with profits as jokes.", "They speak of abundance, of riches untold,", "Yet somehow, it’s them who count all the gold."]], ["v", ["And the sober? Oh yes, let’s laugh at the straight,", "Those who preach balance, yet thrive on their fate.", "For rules and restrictions are written by those,", "Who sip their own nonsense in cups no one knows."]], ["v", ["And then came the laws, the loopholes so grand,", "A system of order that few understand.", "For crime’s not the issue, nor justice so bright,", "But rather, who’s holding the pen when they write."]], ["v", ["The media he mocked, their headlines so bleak,", "Screaming of doom just three times a week.", "Their truths are elastic, their facts are for sale,", "For fear, dear scholars, is what they unveil."]], ["v", ["And war, oh war! The sport of the wise,", "Led by old men with fire in their eyes.", "They call it for freedom, for justice, for peace,", "Yet profits are counted before the deceased."]], ["v", ["And so, dear students, what have we learned?", "That rules are for fools, and books should be burned?", "That truth is a myth, a well-crafted lie?", "That life’s just a scam with no reason why?"]], ["v", ["Perhaps… perhaps, but think once again,", "For nonsense itself is a powerful pen.", "And if there’s one lesson from Foshworthy’s tale,", "It’s that the best way to win… is to never set sail."]]]},
    {"t": "The Sacred Charta of Free Sillysism", "p": "The Continuing", "b": [["h", "Verse 1"], ["v", ["Oh ye seekers of nonsense and wisdom combined,", "Welcome to Sillysism—unshackle your mind!", "No logic too sacred, no thought too confined,", "For rules are but jokes that the dull have designed."]], ["h", "Verse 2"], ["v", ["Thou shalt question what others obey,", "The laws, the traditions, the prices they pay.", "For if sense made sense, then why all the strife?", "And why does a tie mean success in this life?"]], ["h", "Verse 3"], ["v", ["To be a true Silly, you must first unlearn,", "Forget what they told you—let reason adjourn.", "For serious men write the dumbest decrees,", "Yet mock those who dance with the wind and the breeze."]], ["h", "Verse 4"], ["v", ["Thou shalt mock the pundits so wise,", "Who claim they see truth through media’s disguise.", "For headlines are prophets of doom on repeat,", "And fear is the price that they sell in the street."]], ["h", "Verse 5"], ["v", ["Thou shalt laugh at the markets so grand,", "Where fools trade air with invisible hands.", "Where wealth is a number, a whisper, a guess,", "And fortunes are built on the art of “Unless.”"]], ["h", "Verse 6"], ["v", ["Thou shalt mock the leaders of war,", "Who send forth the young while they watch from afar.", "Who speak of great battles, of honor and might,", "Yet count their investments by candlelight."]], ["h", "Verse 7"], ["v", ["A true Silly must see the absurd,", "A sermon of wealth? The preacher’s preferred!", "For those who sell faith with a price on the side,", "Have wallets more blessed than the ones they have tied."]], ["h", "Verse 8"], ["v", ["Thou shalt honor Sir Fosh, our Prophet of Jest,", "Who fooled all the wise and conquered the test.", "For if laws can be bent and rules can be played,", "Then why take life seriously? Why be afraid?"]], ["h", "Verse 9"], ["v", ["To be truly devout, one must break a small law,", "Not crimes of great harm, just loopholes in awe.", "For if ink on a page can define right and wrong,", "Then what is a rule but a bureaucrat’s song?"]], ["h", "Verse 10"], ["v", ["Fashion, oh fashion, thou shalt expose!", "For beauty’s a scam and vanity knows.", "A brand with no sleeves, a shoe without lace,", "Yet priced like a diamond, parading in grace."]], ["h", "Verse 11"], ["v", ["A Silly must never, no never be dull,", "For laughter is wisdom, and boredom’s the cull.", "Thou shalt mock with a tone most refined,", "Like a scholar, a king, yet a fool most aligned."]], ["h", "Verse 12"], ["v", ["And when asked for your stance on the matters of state,", "Reply with a shrug—\"Let nonsense dictate!\"", "For wisdom and madness are closer than kin,", "And truth is just noise with a suit and a grin."]], ["h", "Verse 13"], ["v", ["So go forth, dear Sillys, and question it all!", "The grand and the mighty, the laws that befall.", "For seriousness crumbles, and logic’s a game,", "But Sillysism, dear friends, shall forever remain!"]]]},
    {"t": "The Grand Inquiry of the Sensible Fools", "p": "The Continuing", "b": [["v", ["If laws are just ink and justice is blind,", "Then why does wealth always see what it finds?", "If prisons hold thieves but banks rob the land,", "Then why shake the warden’s obedient hand?"]], ["v", ["If leaders love peace but fund every fight,", "Then why do their pockets grow fat overnight?", "If borders are sacred but drawn with a pen,", "Then who was the first to say, “This is my land”?"]], ["v", ["If news tells the truth but sponsors decide,", "Then why does a lie pay more than what’s right?", "If freedom means speech but speech has a fee,", "Then who owns the words that are meant to be free?"]], ["v", ["If knowledge is power but school is a jail,", "Then why do the brightest still struggle and fail?", "If exams test minds but life tests the soul,", "Then why does a paper decide the whole goal?"]], ["v", ["If ads sell us dreams that crumble on touch,", "Then why do we chase what matters so much?", "If diamonds are rare but shops overflow,", "Then why do they shine on the hands of the low?"]], ["v", ["If war is for honor but honor is dead,", "Then why do the brave come home with no bread?", "If medals mean courage but courage means loss,", "Then why do the winners all weep for the cost?"]], ["v", ["If faith is a virtue but churches sell grace,", "Then why must salvation have premium rates?", "If riches mean blessings but greed is a sin,", "Then why does the preacher wear gold on his skin?"]], ["v", ["If work makes us noble but rest is the dream,", "Then why is exhaustion the boss’s routine?", "If passion is purpose but wages decide,", "Then why must the artist just struggle and hide?"]], ["v", ["If fashion’s expression but trends set the rules,", "Then why are the stylish just walking buffoons?", "If beauty’s inside but filters are king,", "Then why do the real ones feel like a sin?"]], ["v", ["If love is so pure but comes with a cost,", "Then why does divorce seem cheaper than trust?", "If marriage is sacred but lawyers get paid,", "Then why does commitment come with a blade?"]], ["v", ["If leaders are chosen but vote counts are blurred,", "Then why do the richest decide what is heard?", "If power is service but service is pain,", "Then why do the rulers keep changing the game?"]], ["v", ["If logic is sharp but humor is wise,", "Then why do the fools see through all the lies?", "If serious men rule but still miss the mark,", "Then why do the jesters light up the dark?"]], ["v", ["If breaking the rules is what makes us free,", "Then why do we bow to bureaucracy?", "If rebels are fools but heroes the same,", "Then who writes the script for this ludicrous game?"]], ["v", ["If life is so short but work takes it all,", "Then why do we waste it in cubicles small?", "If death is the end but savings are hoarded,", "Then why are the coffins so finely imported?"]], ["v", ["If lawyers seek truth but twist it for fees,", "Then why does the verdict depend on degrees?", "If justice is blind but money’s in sight,", "Then why do the guilty still sleep well at night?"]], ["v", ["If freedom is speech but rebels are hushed,", "Then why is the silence so loudly discussed?", "If power corrupts but virtue is weak,", "Then why do the honest starve as they speak?"]], ["v", ["If debt makes us slaves but banks build the chains,", "Then why do they smile while we drown in remains?", "If printing more cash can make things all right,", "Then why does inflation keep kissing the sky?"]], ["v", ["If silence is golden but secrets are priced,", "Then why do the whispers hold more than advice?", "If scandal is bad but gossip is news,", "Then why do we tune in for headline abuse?"]], ["v", ["If kings are just men but men love their kings,", "Then why do we cheer as they tighten the strings?", "If history’s written by victors alone,", "Then why trust the past when the past was a throne?"]], ["v", ["If purpose is meaning but meaning is lost,", "Then why does existence demand such a cost?", "If destiny’s real but choice is a trick,", "Then why does free will still come with a script?"]], ["v", ["If everything’s silly but serious folks reign,", "Then why does their wisdom still circle the drain?", "If nonsense and sense are twin in the end,", "Then why not let Sillysism ascend?"]], ["v", ["So ask and ask and never be sure,", "For answers are prisons, but questions endure.", "The world is a joke, a lie, a disguise—", "But only the Silly can open their eyes."]]]},
    {"t": "Conclusions and Final Thoughts", "p": "Closing", "b": [["p", "And so, dear reader, we reach the grand finale of The Silly Testament: A Scholar’s Guide to Absolute Nonsense. If you were expecting some deep, life-changing wisdom, I regret to inform you that this book has never pretended to be anything but a playful exploration of life’s absurdities."], ["p", "Throughout these pages, we have questioned everything—laws, traditions, business, politics, and even the so-called logic that holds society together. We have poked fun at the things people take too seriously and exposed the contradictions hiding in plain sight. But most importantly, we have celebrated the power of silliness, critical thinking, and the joy of looking at the world through a more humorous lens."], ["p", "This book is not an attack on anyone. It does not promote harm, hatred, or reckless behavior. Instead, it serves as an invitation to question, to laugh, and to recognize that even the most serious institutions are not immune to a little bit of nonsense."], ["p", "So, what now? Do you overthrow governments? Challenge your professors? Run naked through the streets declaring yourself the Grandmaster of Sillysism? No—unless, of course, it’s legal in your country. Instead, take this book as a gentle reminder that questioning the status quo is healthy, that humor is a powerful tool, and that sometimes, the silliest person in the room is the one who sees the truth most clearly."], ["p", "And with that, I bid you farewell. Go forth, be silly, be thoughtful, and most importantly—never stop questioning."], ["s", "With utmost nonsense and scholarly mischief,"], ["s", "Professor Gigglesworth von Buffoonery, PhD (in Preposterous Studies)"]]},
    {"t": "Acknowledgements", "p": "Closing", "b": [["p", "Writing The Silly Testament: A Scholar’s Guide to Absolute Nonsense has been a journey of the highest absurdity, and I must extend my most preposterously profound gratitude to those who have helped shape this literary masterpiece of madness."], ["p", "First, to Professor Ludmilla P. Noodledoodle, whose groundbreaking research in Applied Silliness and Quantum Buffoonery has shown the world that foolishness is not a weakness but a misunderstood superpower. Your contributions to the field of organized absurdity will not go unnoticed (or understood)."], ["p", "A special commendation to Maximilian Frothmuffin, a world-renowned preacher of Sillysism, an architect of mayhem, and a professor of experimental absurdity. His legendary ventures—including legally becoming a billionaire’s heir, running an airline for fun, and fooling entire nations with his aristocratic nonsense—have pushed the boundaries of what civilization can tolerate. His commitment to Sillysism is a beacon of inspiration to all who wish to challenge common sense and embrace delightful idiocy."], ["p", "To the Institute of Advanced Nonsense and Sillogical Studies, whose mission to uphold the fine balance between intellect and pure absurdity has given legitimacy to the work of fools everywhere. And to Chancellor Lady Wobblebottom of the University of Unhinged Enlightenment, your review of this book serves as proof that even the most esteemed scholars can appreciate a well-timed mockery of reality."], ["p", "A heartfelt nod to the many political thinkers, legal masterminds, business magnates, and fashion designers whose decisions have created enough loopholes, contradictions, and outright nonsense to keep this book overflowing with material. Without your daily displays of foolish brilliance, my task would have been significantly harder."], ["p", "To the devoted followers of Sillysism, who courageously question the unquestionable, break rules that were never meant to exist, and seek wisdom in the most ridiculous of places—this book is for you. May your journey through life be filled with confusion, unexpected laughter, and the occasional spontaneous roundabout purchase."], ["p", "And lastly, to you, dear reader—whether you are here seeking enlightenment or simply something to stare at while pretending to work—I am immensely grateful. Your willingness to entertain absurdity proves that nonsense is, in fact, humanity’s greatest intellectual achievement."], ["p", "May you forever question, forever mock, and forever revel in the joyful idiocy of existence."], ["s", "With the highest level of unseriousness,"], ["s", "Professor Gigglesworth von Buffoonery, PhD (in Preposterous Studies)"]]},
    {"t": "A Final Note from the Desk of Prof. Gigglesworth von Buffoonery, PhD (in Preposterous Studies)", "p": "Closing", "b": [["p", "Dear Esteemed Scholars of Absolute Nonsense,"], ["p", "If you've made it this far, congratulations! You have successfully endured the intellectual rollercoaster of absurdity, irony, and unnecessary but highly necessary questioning. You are now a certified practitioner of Sillysism, equipped with the tools to challenge logic, defy seriousness, and mock reality itself."], ["p", "I must warn you, however, that this book was written under strictly controlled conditions of zero seriousness. Any attempts to extract wisdom from it are at your own risk. Any life-changing epiphanies you may experience are purely accidental and should be ignored immediately."], ["p", "Remember: No goats, hedgehogs, or sensible individuals were harmed in the making of this book."], ["p", "No holy relics were disrespected (except those made of overpriced designer fabrics). No copyright was infringed, at least not intentionally (I have an imaginary lawyer on standby just in case)."], ["p", "And most importantly, no refunds. You already paid for this nonsense."], ["p", "Go forth and spread the gospel of Sillysism responsibly—or irresponsibly, I really don’t care. But whatever you do, don’t take this world too seriously, because it certainly doesn’t take you seriously either."], ["p", "With utmost silliness, Prof. Gigglesworth von Buffoonery, PhD (in Preposterous Studies)"], ["p", "Supreme Chancellor of the Absurd & Keeper of the Holy Roundabout"], ["p", "P.S. If you find a deeper meaning in any of these poems, kindly return it to its rightful owner."]]}
  ]
}
];
